export function toFrequency(midiNote: number) {
  return 440 * Math.pow(2, (midiNote - 69) / 12);
}

export function linearRead(xs: Float32Array, idx: number) {
  const whole = Math.floor(idx);
  const frac = idx - whole;
  const x0 = xs[whole < 0 ? xs.length - 1 : whole];
  const x1 = xs[(whole + 1) % xs.length];
  return x0 + frac * (x1 - x0);
}

// adapted from https://github.com/pichenettes/stmlib/blob/master/dsp/dsp.h
export function interpolatedRead(xs: Float32Array, idx: number) {
  const whole = Math.floor(idx);
  const frac = idx - whole;
  const xm1 = xs[whole - 1 < 0 ? xs.length - 1 : whole - 1];
  const x0 = xs[whole];
  const x1 = xs[(whole + 1) % xs.length];
  const x2 = xs[(whole + 2) % xs.length];
  const c = (x1 - xm1) / 2;
  const v = x0 - x1;
  const w = c + v;
  const a = w + v + (x2 - x0) / 2;
  const bNeg = w + a;
  return ((a * frac - bNeg) * frac + c) * frac + x0;
}

export function fastTanh(x: number) {
  if (x > 3) {
    return 1;
  } else if (x < -3) {
    return -1;
  } else {
    const x2 = x * x;
    return (x * (27 + x2)) / (27 + 9 * x2);
  }
}

export function clamp(v: number, min: number, max: number) {
  return Math.max(min, Math.min(v, max));
}

/**
 * Amplitude multiplier for patch `noteVel` from MIDI velocity (0–127).
 * Linear vel/127 makes medium and soft hits much quieter than they sound; loudness is roughly logarithmic,
 * so we map normalized velocity through a dB range (exponential gain), similar to a synth velocity curve.
 */
export function midiVelocityToNoteVelGain(vel: number, minDbWhenSoft = -20): number {
  const t = clamp(vel / 127, 0, 1);
  const db = minDbWhenSoft * (1 - t);
  return Math.pow(10, db / 20);
}

/**
 * Swipe speed that counts as strumming as hard as you can, in CSS pixels per millisecond.
 * Speed is deliberately *not* measured in pad heights per millisecond: a pad on an iPad is about
 * twice as tall as a pad on an iPhone, so the same real-world strumming speed would register as
 * only half the velocity on the bigger screen. A CSS pixel, on the other hand, is roughly the same
 * physical size on every device (~1/150" on phones, ~1/132" on tablets), so measuring in CSS pixels
 * keeps the dynamics consistent across screen sizes.
 */
const STRUM_SPEED_FOR_MAX_VELOCITY = 6;

/** Velocity for a strum pad that's tapped or held rather than swiped across (e.g. for arpeggios). */
export const STRUM_TAP_VELOCITY = 0.7;

/** Vertical swipe speed (CSS px/ms) → normalized strum intensity (0–1). */
export function strumSwipeSpeedToNormalizedVel(speedPxPerMs: number): number {
  return clamp(speedPxPerMs / STRUM_SPEED_FOR_MAX_VELOCITY, 0, 1);
}

/** Normalized strum intensity → MIDI velocity with a concave curve so soft strums stay soft. */
export function strumTouchVelocityToMidi(normalizedVel: number, curve = 1.7): number {
  const curved = Math.pow(clamp(normalizedVel, 0, 1), curve);
  return Math.max(1, Math.round(127 * curved));
}

export function makeSharedFloat32Array(length: number): Float32Array<any> {
  return new Float32Array(new SharedArrayBuffer(length * 4));
}

export class SpeedTracker {
  readonly windowMs = 150;
  history: { pos: number; t: number }[] = [];

  addPos(pos: number) {
    this.history.push({ pos, t: performance.now() });
  }

  /** the current speed, in pixels per millisecond */
  get speed() {
    const now = performance.now();
    this.history = this.history.filter(({ t }) => now - t <= this.windowMs);

    if (this.history.length < 2) {
      return 0;
    }

    let totalDistance = 0;
    for (let idx = 1; idx < this.history.length; idx++) {
      totalDistance += Math.abs(this.history[idx].pos - this.history[idx - 1].pos);
    }

    const dt = this.history[this.history.length - 1].t - this.history[0].t;
    return totalDistance / dt;
  }
}

export function pad(n: number, numDigits = 2) {
  let s = '' + n;
  while (s.length < numDigits) {
    s = '0' + s;
  }
  return s;
}
